import {registerEditor,markEditorSaved} from './edit-guard.mjs';
import {outlineChapters,buildOutline,reconcileSections,composeBody} from './writing-model.mjs';
import {projects,preferences,recordTask} from './state.mjs';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const writingTasks=[['topic','智能选题','◇'],['proposal','开题报告','▤'],['summary','文献综述','▥'],['writing','论文写作','✎'],['course','课程作业','▱'],['review','导师意见修改','♧']];
const paths={topic:'M9 18h6M10 21h4M8 14a6 6 0 1 1 8 0l-1 3H9z',proposal:'M14 3H5v18h14V8zM14 3v6h5M8 13h8m-8 4h6',summary:'M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1zm0 0v15',writing:'m15 5 4 4M4 20l4-1L20 7a3 3 0 0 0-4-4L4 15z',course:'m3 8 9-5 9 5-9 5zM6 10v6l6 3 6-3v-6',review:'M5 21v-3a7 7 0 0 1 14 0v3M16 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0',upload:'M12 16V4m-5 5 5-5 5 5M5 12H3v9h18v-9h-2'};
const glyph=id=>`<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[id]||paths.writing}"/></svg>`;
export const taskNav=id=>`<nav class="writing-task-nav" aria-label="写作任务">${writingTasks.map(([key,label])=>`<a href="#tool/${key}" class="${key===id?'selected':''}" ${key===id?'aria-current="page"':''}>${glyph(key)}${label}</a>`).join('')}</nav>`;
const chapters=outlineChapters;
const read=()=>{try{const v=JSON.parse(localStorage.getItem('paperknow-drafts')||'[]');return Array.isArray(v)?v:[];}catch{return[];}};
export function mountWriting(draftId,projectId,ctx){const pref=preferences(),context=projects().find(p=>p.id===projectId);const loaded=read().find(d=>String(d.id)===String(draftId));let savedId=loaded?.id,content=loaded?.outlineText??loaded?.text??'',material=loaded?.material||'',fileName=loaded?.fileName||'',materialState=loaded?.materialState||'saved',parsing=false,disposed=false,editing=false,outlineConfirmed=!!loaded?.outlineConfirmed,bodySections=Array.isArray(loaded?.bodySections)?loaded.bodySections.map(s=>({...s})):[],workflowStage=loaded?.outlineConfirmed?3:1;
if(!content&&loaded?.html&&!loaded?.outlineText){const d=document.createElement('div');d.innerHTML=loaded.html;d.querySelectorAll('p,h3,h4').forEach(n=>n.append(document.createTextNode('\n')));content=d.textContent||'';}
const mode=loaded?.mode==='论文初稿'?'毕业论文':loaded?.mode||'毕业论文';
document.querySelector('.dashboard').classList.remove('category-view');document.querySelector('.dashboard').classList.add('creation-page');document.querySelector('.breadcrumb strong').textContent='研究工作台 / AI 写作';document.querySelectorAll('.sidebar .nav-link').forEach(a=>a.classList.toggle('active',a.getAttribute('href')==='#category/writing'));
document.querySelector('.dashboard').innerHTML=`<div class="creation-heading"><h1>创建论文</h1><p>从研究信息开始，确认框架后分章节写作。</p></div>${taskNav('writing')}<nav class="writing-steps" aria-label="论文写作步骤">${['填写研究信息','确认论文大纲','分章节写作','编辑与导出'].map((name,i)=>`<button type="button" data-writing-step="${i+1}"><span>${i+1}</span>${name}</button>`).join('')}</nav><div class="creation-grid"><section class="card creation-input"><h2>研究信息</h2><p class="section-hint">填写题目与学段，其他要求可稍后补充。</p><div class="creation-actions"><button type="button" class="btn secondary" id="writing-save">保存草稿</button><button type="submit" form="writing-form" class="btn primary" id="writing-generate">生成大纲模板 <span aria-hidden="true">→</span></button></div><p class="creation-disclaimer">当前生成本地结构模板，AI 服务尚未接入；材料仅解析，不自动用于生成。</p><form id="writing-form"><label for="writing-project">所属项目（可选）</label><select id="writing-project"><option value="">未归入项目</option>${projects().map(p=>`<option value="${esc(p.id)}" ${p.id===(loaded?.projectId||projectId)?'selected':''}>${esc(p.name)}${p.status==='archived'?'（已归档）':''}</option>`).join('')}</select><fieldset class="type-field"><legend>写作类型</legend><div class="type-options">${['毕业论文','课程论文','期刊论文','SCI 论文'].map((m,i)=>`<label><input type="radio" name="writing-mode" value="${m}" ${m===mode?'checked':''}><span><i aria-hidden="true">${glyph(['course','proposal','summary','review'][i])}</i>${m}</span></label>`).join('')}</div></fieldset><div class="creation-row"><div><label for="writing-degree">学段</label><select id="writing-degree">${['专科','本科','硕士','博士','科研人员'].map(d=>`<option ${d===(loaded?.degree||context?.degree||pref.degree).replace('论文','')?'selected':''}>${d}</option>`).join('')}</select></div><div><label for="writing-major">学科专业</label><input id="writing-major" maxlength="100" value="${esc(loaded?.major??context?.major??pref.major)}" placeholder="例如：教育学"></div></div><label for="writing-title">论文题目 / 研究方向 <span class="writing-required">*</span></label><div class="counted-field"><textarea id="writing-title" aria-required="true" rows="2" maxlength="200" placeholder="例如：人工智能辅助课堂学习反馈的应用研究">${esc(loaded?.title??context?.name??'')}</textarea><span id="title-count"></span></div><details class="writing-options" ${loaded?.requirements||loaded?.method||loaded?.targetWords?'open':''}><summary>写作要求 <small>（可选）</small></summary><div class="creation-row"><div><label for="writing-target">目标字数</label><input id="writing-target" type="number" min="500" max="100000" step="100" value="${esc(loaded?.targetWords||'')}" placeholder="例如：8000"></div><div><label for="writing-method">研究方法</label><input id="writing-method" maxlength="100" value="${esc(loaded?.method||'')}" placeholder="例如：问卷调查与访谈"></div></div><label for="writing-requirements">学校 / 导师要求</label><div class="counted-field"><textarea id="writing-requirements" rows="3" maxlength="2000" placeholder="填写研究重点、方法或导师要求…">${esc(loaded?.requirements||'')}</textarea><span id="requirements-count"></span></div></details><details class="writing-material-options" ${fileName?'open':''}><summary>参考材料 <small>（可选）</small></summary><label for="writing-file">参考材料（可选，当前支持一份）</label><label class="writing-upload" id="writing-drop" for="writing-file"><span class="upload-symbol" aria-hidden="true">${glyph('upload')}</span><span><b>上传文档或拖拽至此</b><small>DOCX / PDF / TXT · 最大 50MB</small></span><input id="writing-file" type="file" accept=".docx,.pdf,.txt"></label><div id="material-file-card" hidden></div><label class="material-purpose-label" for="material-purpose">材料用途</label><select id="material-purpose">${['参考文献','导师要求','已有草稿','格式要求'].map(n=>`<option ${n===loaded?.materialPurpose?'selected':''}>${n}</option>`).join('')}</select><p class="material-status" id="material-status" role="status"></p><button type="button" id="material-toggle" class="material-toggle" hidden>查看解析正文</button><div id="material-area" hidden><label for="writing-material">解析正文（可核对和编辑）</label><textarea id="writing-material" rows="5" maxlength="20000">${esc(material)}</textarea><button type="button" id="material-remove" class="material-toggle">移除参考材料</button></div><div id="writing-error" role="alert" class="error-text"></div></details></form></section><section class="card creation-output"><div class="preview-heading"><h2>论文框架预览</h2><span class="preview-tag" id="preview-tag">${content?'已保存内容':'大纲示例'}</span></div><p class="writing-example-note" id="writing-example-note">当前展示示例；生成后可调整章节与顺序。</p><div id="writing-outline-area"><article class="outline-paper" id="outline-paper"></article><textarea id="outline-editor" aria-label="编辑论文大纲" hidden></textarea><div class="creation-actions"><button class="btn secondary" id="outline-edit">✎　编辑大纲</button><button class="btn secondary" id="outline-export">↓　导出大纲 TXT</button></div><p class="writing-next-note">调整并确认大纲后，可分章节填写正文。</p><button type="button" class="btn primary full" id="outline-confirm">确认大纲，开始写作 →</button></div><section id="writing-body-area" hidden><p class="writing-manual-note">当前为手动写作与本地保存，未调用 AI。请依据真实研究填写。</p><label for="body-chapter">章节目录</label><select id="body-chapter"></select><p id="body-retained-note" class="writing-next-note"></p><textarea id="body-editor" rows="15" maxlength="100000" aria-label="编辑章节正文" placeholder="填写当前章节正文…"></textarea><div class="writing-body-count" id="body-count"></div><div class="creation-actions"><button class="btn secondary" id="body-save" type="button">保存正文</button><button class="btn primary" id="body-finish" type="button">编辑与导出 →</button></div></section><section id="writing-export-area" hidden><h3>导出当前草稿</h3><p class="writing-manual-note">导出你已填写的正文，空章节不会填充内容。当前支持 TXT，不包含 Word 排版。</p><pre id="body-preview"></pre><div class="creation-actions"><button class="btn secondary" type="button" id="body-back">返回章节编辑</button><button class="btn primary" type="button" id="body-export">导出正文 TXT</button></div></section><button id="outline-copy" class="material-toggle" hidden>复制大纲全文</button><p id="writing-status" role="status" class="material-status"></p></section></div><div class="creation-trust">♧　本地保存 · 请及时导出备份；参考材料在当前浏览器处理，请核对引用来源。</div>`;
const $=s=>document.querySelector(s),alive=()=>$('#writing-form')!==null&&!disposed;
const values=()=>({projectId:$('#writing-project').value,title:$('#writing-title').value.trim(),degree:$('#writing-degree').value,major:$('#writing-major').value.trim(),mode:$('input[name="writing-mode"]:checked')?.value||'毕业论文',targetWords:$('#writing-target').value,method:$('#writing-method').value.trim(),materialPurpose:$('#material-purpose').value,requirements:$('#writing-requirements').value.trim()});
function render(){const v=values();$('#outline-paper').innerHTML=content?`<div class="outline-content">${content.split('\n').filter(Boolean).map((line,i)=>`<p class="${i===0?'outline-title':i===1?'outline-meta':line.startsWith('　')?'outline-child':/^第.+章/.test(line)?'outline-chapter':''}">${esc(line)}</p>`).join('')}</div>`:`<h3>${esc(v.title||'人工智能辅助课堂学习反馈的应用研究')}</h3><p class="outline-meta">${esc(v.degree)} · ${esc(v.major||'学科待填写')}</p><div class="outline-content">${chapters.map(l=>`<p class="${l.startsWith('　')?'outline-child':'outline-chapter'}">${esc(l)}</p>`).join('')}</div>`;$('#outline-export').disabled=!content;$('#outline-edit').disabled=!content;$('#outline-confirm').disabled=!content;$('#writing-example-note').hidden=!!content;updateWorkflow();}
function count(){ $('#title-count').textContent=$('#writing-title').value.length+'/200';$('#requirements-count').textContent=$('#writing-requirements').value.length+'/2000';if(!content)render();}
function sync(){if(editing)content=$('#outline-editor').value;}
$('#writing-title').addEventListener('input',count);$('#writing-requirements').addEventListener('input',count);$('#writing-degree').addEventListener('change',()=>{if(!content)render();});$('#writing-major').addEventListener('input',()=>{if(!content)render();});count();render();
function updateWorkflow(){document.querySelectorAll('[data-writing-step]').forEach(b=>{const step=Number(b.dataset.writingStep);b.classList.toggle('active',step===workflowStage);if(step===workflowStage)b.setAttribute('aria-current','step');else b.removeAttribute('aria-current');b.disabled=step===2?!content:step>=3?!outlineConfirmed:false;});$('#writing-outline-area').hidden=workflowStage>=3;$('#writing-body-area').hidden=workflowStage!==3;$('#writing-export-area').hidden=workflowStage!==4;$('.creation-output h2').textContent=workflowStage===3?'分章节写作':workflowStage===4?'编辑与导出':'论文框架预览';}
function renderMaterial(){$('#material-file-card').hidden=!material;$('#material-file-card').innerHTML=material?`<div><b>${esc(fileName||'参考材料')}</b><small>${materialState==='parsed'?'已解析':materialState==='edited'?'正文已编辑':'已保存材料'} · ${material.length.toLocaleString('zh-CN')} 字符</small></div><button type="button" id="material-card-remove" aria-label="移除参考材料">×</button>`:'';if(material)$('#material-card-remove').addEventListener('click',()=>$('#material-remove').click());}
function bodyCount(){const text=$('#body-editor').value;$('#body-count').textContent=`当前章节 ${Array.from(text).length.toLocaleString('zh-CN')} 字符 · 修改后请保存`;}
function showBody(){const old=$('#body-chapter').value;$('#body-chapter').innerHTML=bodySections.map(s=>`<option value="${esc(s.id)}">${esc(s.title)}${s.retained?'（保留旧章节）':''}</option>`).join('');if(bodySections.some(s=>s.id===old))$('#body-chapter').value=old;loadChapter();updateWorkflow();}
function loadChapter(){const s=bodySections.find(s=>s.id===$('#body-chapter').value);$('#body-editor').value=s?.text||'';$('#body-retained-note').textContent=s?.retained?'此章节不在当前大纲中，已有正文仍保留，请手动核对。':'';bodyCount();}
$('#body-editor').addEventListener('input',()=>{const section=bodySections.find(s=>s.id===$('#body-chapter').value);if(section)section.text=$('#body-editor').value;bodyCount();$('#writing-status').textContent='正文已修改，请保存后离开。';});
$('#body-chapter').addEventListener('change',loadChapter);
$('#outline-confirm').addEventListener('click',()=>{sync();if(!content.trim())return;bodySections=reconcileSections(content,bodySections);outlineConfirmed=true;workflowStage=3;editing=false;$('#outline-editor').hidden=true;$('#outline-paper').hidden=false;$('#outline-edit').textContent='✎　编辑大纲';showBody();$('#preview-tag').textContent='手动写作';$('#writing-status').textContent='大纲已确认，可逐章填写正文；请保存以保留进度。';});
$('#body-save').addEventListener('click',()=>$('#writing-save').click());
function showExport(){workflowStage=4;$('#body-preview').textContent=composeBody(values(),bodySections);$('#body-export').disabled=!bodySections.some(s=>s.text.trim());updateWorkflow();$('#preview-tag').textContent='本地草稿';}
$('#body-finish').addEventListener('click',showExport);
$('#body-back').addEventListener('click',()=>{workflowStage=3;showBody();});
$('#body-export').addEventListener('click',()=>{const text=composeBody(values(),bodySections);if(!bodySections.some(s=>s.text.trim()))return;const url=URL.createObjectURL(new Blob([text],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(values().title||'论文草稿').replace(/[\\/:*?"<>|]/g,'_')+'-正文.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#writing-status').textContent='已发起正文 TXT 下载。';});
$('[data-writing-step="1"]').addEventListener('click',()=>{workflowStage=1;updateWorkflow();$('#writing-title').focus();});
$('[data-writing-step="2"]').addEventListener('click',()=>{workflowStage=2;updateWorkflow();});
$('[data-writing-step="3"]').addEventListener('click',()=>{workflowStage=3;showBody();});
$('[data-writing-step="4"]').addEventListener('click',showExport);
$('#writing-project').addEventListener('change',()=>{const p=projects().find(p=>p.id===$('#writing-project').value);if(!p)return;if(!$('#writing-major').value)$('#writing-major').value=p.major||'';if(!$('#writing-title').value)$('#writing-title').value=p.name||'';if(p.degree)$('#writing-degree').value=p.degree;count();});
$('#writing-material').addEventListener('input',()=>{material=$('#writing-material').value;materialState='edited';renderMaterial();$('#material-status').textContent='材料正文已编辑，请保存草稿。';});
if(outlineConfirmed){if(!bodySections.length)bodySections=reconcileSections(content);showBody();}renderMaterial();
$('#outline-editor').addEventListener('input',()=>{$('#writing-status').textContent='大纲已修改，请完成编辑并保存。';});
$('#writing-form').addEventListener('submit',e=>{e.preventDefault();if(parsing)return;const v=values();if(v.title.length<2){$('#writing-error').textContent='请填写至少 2 个字的论文题目或研究方向。';$('#writing-title').focus();return;}$('#writing-error').textContent='';if(content&&!window.confirm('重新生成会替换当前大纲。已有章节正文会保留，确认后请核对章节关联。'))return;content=buildOutline(v);outlineConfirmed=false;workflowStage=2;editing=false;$('#outline-editor').hidden=true;$('#outline-paper').hidden=false;$('#outline-edit').textContent='✎　编辑大纲';$('#preview-tag').textContent='本地模板';render();$('#writing-status').textContent='大纲模板已生成，可编辑、保存和导出。';});
$('#outline-edit').addEventListener('click',()=>{if(!content)return;outlineConfirmed=false;workflowStage=2;updateWorkflow();if(editing){sync();editing=false;render();}else{editing=true;$('#outline-editor').value=content;}$('#outline-editor').hidden=!editing;$('#outline-paper').hidden=editing;if(editing)$('#outline-editor').focus();$('#outline-edit').textContent=editing?'完成编辑':'✎　编辑大纲';});
$('#writing-save').addEventListener('click',()=>{if(parsing)return;if(!$('#writing-form').reportValidity())return;sync();const v=values();if(v.title.length<2){$('#writing-error').textContent='保存前请填写至少 2 个字的题目或研究方向。';return;}$('#writing-error').textContent='';material=$('#writing-material').value;const rows=read(),previous=rows.find(d=>String(d.id)===String(savedId)),now=new Date().toISOString(),hasBody=bodySections.some(s=>s.text.trim()),text=hasBody?composeBody(v,bodySections):content;const item={...previous,...v,id:savedId||crypto.randomUUID(),tool:'writing',createdAt:previous?.createdAt||now,updatedAt:now,text,html:text.split('\n').map(l=>`<p>${esc(l)}</p>`).join(''),outlineText:content,outlineConfirmed,bodySections,workflowStage,material,materialState,fileName,stage:hasBody?'body':content?'outline':'draft',date:new Date().toLocaleString('zh-CN')};const drafts=read(),i=drafts.findIndex(d=>String(d.id)===String(item.id));if(i>=0)drafts[i]=item;else drafts.unshift(item);try{localStorage.setItem('paperknow-drafts',JSON.stringify(drafts));savedId=item.id;markEditorSaved();$('#writing-status').textContent='已保存到当前浏览器，可在“我的成果”继续编辑。';$('#preview-tag').textContent=hasBody?'已保存正文':'已保存内容';try{recordTask({id:'draft-'+item.id,title:item.title,kind:hasBody?'本地正文保存':content?'本地大纲保存':'本地草稿保存',status:'completed',url:'#draft/'+item.id});}catch{$('#writing-status').textContent+=' 任务记录未保存。';}}catch{$('#writing-status').textContent='保存失败，浏览器空间可能不足，请先导出备份。';}});
$('#outline-export').addEventListener('click',()=>{sync();if(!content)return;const url=URL.createObjectURL(new Blob([content],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=(values().title||'论文大纲').replace(/[\\/:*?"<>|]/g,'_')+'.txt';document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);$('#outline-copy').hidden=false;$('#writing-status').textContent='已发起 TXT 下载。若浏览器未保存文件，可复制大纲全文。';});
$('#outline-copy').addEventListener('click',async()=>{sync();try{await navigator.clipboard.writeText(content);$('#writing-status').textContent='大纲已复制。';}catch{editing=true;$('#outline-editor').value=content;$('#outline-editor').hidden=false;$('#outline-paper').hidden=true;$('#outline-editor').focus();$('#outline-editor').select();$('#outline-edit').textContent='完成编辑';$('#writing-status').textContent='请使用系统复制快捷键复制已选中的大纲。';}});
async function parse(file){if(!file||parsing)return;const form=$('#writing-form');if(file.size>50*1024*1024){$('#material-status').textContent='请选择不超过 50MB 的文件。';return;}if(!/\.(docx|pdf|txt)$/i.test(file.name)){$('#material-status').textContent='仅支持 DOCX、PDF 或 UTF-8 TXT。';return;}parsing=true;$('#writing-save').disabled=true;$('#writing-generate').disabled=true;$('#material-status').textContent='正在本地解析…';try{const {extractFile}=await import('/precheck/assets/parsers.js'),r=await extractFile(file);if(!alive()||$('#writing-form')!==form){disposed=true;return;}if(!r.text.trim())throw new Error('未提取到正文；扫描 PDF 暂不支持，请转换为文本型文档。');if(r.text.length>20000)throw new Error('参考材料超过 20,000 字符，请选择较短的章节。');material=r.text;materialState='parsed';fileName=file.name;$('#writing-material').value=material;$('#material-toggle').hidden=false;renderMaterial();$('#material-status').textContent=`${fileName} · 已解析 ${material.length} 字符${r.warnings.length?' · '+r.warnings.slice(0,2).join('；'):''}`;}catch(err){if(alive()&&$('#writing-form')===form)$('#material-status').textContent=err.message||'解析失败，请检查文件。';}finally{parsing=false;if(alive()&&$('#writing-form')===form){$('#writing-save').disabled=false;$('#writing-generate').disabled=false;$('#writing-file').value='';}}}
$('#writing-file').addEventListener('change',e=>parse(e.target.files[0]));$('#writing-drop').addEventListener('dragover',e=>{e.preventDefault();$('#writing-drop').classList.add('dragover');});$('#writing-drop').addEventListener('dragleave',()=>$('#writing-drop').classList.remove('dragover'));$('#writing-drop').addEventListener('drop',e=>{e.preventDefault();$('#writing-drop').classList.remove('dragover');if(e.dataTransfer.files.length!==1){$('#material-status').textContent='请一次选择一份参考文档。';return;}parse(e.dataTransfer.files[0]);});$('#material-toggle').addEventListener('click',()=>{$('#material-area').hidden=!$('#material-area').hidden;});$('#material-remove').addEventListener('click',()=>{material='';fileName='';$('#writing-material').value='';$('#material-area').hidden=true;$('#material-toggle').hidden=true;$('#material-status').textContent='参考材料已移除，请保存以更新草稿。';renderMaterial();});if(material){$('#material-toggle').hidden=false;renderMaterial();$('#material-status').textContent=`${fileName||'参考材料'} · ${material.length} 字符`;}
if(ctx)registerEditor({label:'论文草稿',ctx,getValue:()=>({...values(),outlineText:editing?$('#outline-editor').value:content,outlineConfirmed,bodySections,material:$('#writing-material').value,fileName}),save:()=>$('#writing-save').click(),busy:()=>parsing,dispose:()=>{disposed=true;}});
}
